pub(crate) async fn fix_files_under(path: &str, files: &mut Vec<String>) {
    let meta = match fs::metadata(std::path::Path::new(&(path)), &fs::Root::Anywhere) {
        Ok(value) => value,
        Err(_error) => {
            files.push(nikaia_std::block::Text::from(path.to_string()));
            return;
        },
    };
    if !meta.is_dir() {
        files.push(nikaia_std::block::Text::from(path.to_string()));
        return;
    }
    let mut found: Vec<String> = vec![];
    let names = match fs::walk(std::path::Path::new(&(path)), &fs::Root::Anywhere).await {
        Ok(value) => value,
        Err(_error) => { return; },
    };
    for name in names.iter() {
        if nikaia_std::index::or(match nikaia_std::fs::path::extension(&(name)).as_ref() {
            Some(__nikaia_it) => Some(nikaia_std::fs::path::text_of(&(__nikaia_it))),
            None => None,
        }, || "".into()) != "nika" { continue; }
        let relative = match nikaia_std::fs::path::to_text(&(name)) {
            Ok(value) => value,
            Err(_error) => { continue; },
        };
        if format!("/{}", relative).contains("/target/") { continue; }
        let base = path.trim_end_matches('/');
        found.push(format!("{}/{}", base, relative));
    }
    found.sort();
    files.extend(found);
}

